// ─────────────────────────────────────────────────────────────────────────────
// 2. THE GENUINE SNAKE ENVIRONMENT (Strict Standard Rules)
// ─────────────────────────────────────────────────────────────────────────────
class SnakeGame {
  constructor(gridSize = 8, rng) {
    this.gridSize = gridSize;
    this.rng = rng || new SeededRNG(42);
    this.reset();
  }

  reset() {
    this.dir = 1; // Start moving RIGHT
    const midX = Math.floor(this.gridSize / 2);
    const midY = Math.floor(this.gridSize / 2);

    this.body = [{ x: midX, y: midY }];
    this.prevBody = [{ x: midX, y: midY }];
    this.score = 0;
    this.stepsSurvived = 0;
    this.stepsWithoutFood = 0;
    this.isDead = false;
    this.hasWon = false;
    this.deathFlash = 0;
    this.deathReason = 'Alive';

    this.spawnFood();
    return this.getObservation();
  }

  spawnFood() {
    const emptyCells = [];
    for (let x = 0; x < this.gridSize; x++) {
      for (let y = 0; y < this.gridSize; y++) {
        let occupied = false;
        for (let i = 0; i < this.body.length; i++) {
          if (this.body[i].x === x && this.body[i].y === y) {
            occupied = true;
            break;
          }
        }
        if (!occupied) emptyCells.push({ x, y });
      }
    }

    if (emptyCells.length === 0) {
      this.hasWon = true;
      this.food = null;
      return;
    }

    const idx = Math.floor(this.rng.next() * emptyCells.length);
    this.food = emptyCells[idx];
  }

  step(relativeAction) {
    if (this.isDead) return { reward: 0, done: true, state: this.getObservation() };

    // Update heading based on relative turn: 0: Straight, 1: Turn Right, 2: Turn Left
    if (relativeAction === 1) {
      this.dir = (this.dir + 1) % 4;
    } else if (relativeAction === 2) {
      this.dir = (this.dir + 3) % 4;
    }

    this.stepsSurvived++;
    this.stepsWithoutFood++;

    // Preserve previous body positions for rendering interpolation
    this.prevBody = this.body.map(seg => ({ ...seg }));

    const head = this.body[0];
    const move = DIRS[this.dir];
    const newHead = { x: head.x + move.x, y: head.y + move.y };

    // 1. Instant Wall Collision Check
    const hitWall = newHead.x < 0 || newHead.x >= this.gridSize || newHead.y < 0 || newHead.y >= this.gridSize;
    if (hitWall) {
      this.isDead = true;
      this.deathReason = 'Wall Collision';
      this.deathFlash = 8;
      return { reward: -10.0, done: true, state: this.getObservation() };
    }

    // 2. Instant Body Collision Check
    let hitBody = false;
    for (let i = 0; i < this.body.length - 1; i++) {
      if (this.body[i].x === newHead.x && this.body[i].y === newHead.y) {
        hitBody = true;
        break;
      }
    }
    if (hitBody) {
      this.isDead = true;
      this.deathReason = 'Self Collision';
      this.deathFlash = 8;
      return { reward: -10.0, done: true, state: this.getObservation() };
    }

    // Advance head
    this.body.unshift(newHead);

    // 3. Food Pickup Check
    if (this.food && newHead.x === this.food.x && newHead.y === this.food.y) {
      this.score++;
      this.stepsWithoutFood = 0;

      // Victory Condition: 100% board fill
      if (this.body.length === this.gridSize * this.gridSize) {
        this.hasWon = true;
        this.isDead = true;
        this.deathReason = 'Victory! Grid Filled';
        return { reward: 100.0, done: true, state: this.getObservation() };
      }

      this.spawnFood();
      return { reward: 10.0, done: false, state: this.getObservation(), foodEaten: true };
    }

    // Pop tail if no food eaten
    this.body.pop();

    // 4. Starvation Loop Prevention
    const maxStarve = Math.max(100, this.body.length * 60);
    if (this.stepsWithoutFood > maxStarve) {
      this.isDead = true;
      this.deathReason = 'Starvation Loop';
      return { reward: -5.0, done: true, state: this.getObservation() };
    }

    // 5. Dense Distance Reward Shaping
    const oldDist = Math.abs(head.x - this.food.x) + Math.abs(head.y - this.food.y);
    const newDist = Math.abs(newHead.x - this.food.x) + Math.abs(newHead.y - this.food.y);
    const reward = newDist < oldDist ? 0.15 : -0.20;

    return { reward, done: false, state: this.getObservation(), foodEaten: false };
  }

  // 16 Egocentric Observation Features
  getObservation() {
    const head = this.body[0];
    const straight = DIRS[this.dir];
    const right = DIRS[(this.dir + 1) % 4];
    const left = DIRS[(this.dir + 3) % 4];

    const isDanger = (x, y) => {
      if (x < 0 || x >= this.gridSize || y < 0 || y >= this.gridSize) return 1.0;
      for (let i = 0; i < this.body.length - 1; i++) {
        if (this.body[i].x === x && this.body[i].y === y) return 1.0;
      }
      return 0.0;
    };

    const raycast = (dx, dy) => {
      let cx = head.x + dx;
      let cy = head.y + dy;
      let dist = 0;
      while (cx >= 0 && cx < this.gridSize && cy >= 0 && cy < this.gridSize) {
        let blocked = false;
        for (let i = 0; i < this.body.length - 1; i++) {
          if (this.body[i].x === cx && this.body[i].y === cy) {
            blocked = true;
            break;
          }
        }
        if (blocked) break;
        dist++;
        cx += dx;
        cy += dy;
      }
      return dist / this.gridSize;
    };

    const obs = new Float32Array(16);
    // 0..2: Danger reflex whiskers
    obs[0] = isDanger(head.x + straight.x, head.y + straight.y);
    obs[1] = isDanger(head.x + right.x, head.y + right.y);
    obs[2] = isDanger(head.x + left.x, head.y + left.y);

    // 3..6: Heading one-hot
    obs[3] = this.dir === 0 ? 1 : 0;
    obs[4] = this.dir === 1 ? 1 : 0;
    obs[5] = this.dir === 2 ? 1 : 0;
    obs[6] = this.dir === 3 ? 1 : 0;

    // 7..10: Food relative quadrant
    const fx = this.food ? this.food.x : head.x;
    const fy = this.food ? this.food.y : head.y;
    obs[7] = fy < head.y ? 1 : 0; // Food UP
    obs[8] = fx > head.x ? 1 : 0; // Food RIGHT
    obs[9] = fy > head.y ? 1 : 0; // Food DOWN
    obs[10] = fx < head.x ? 1 : 0; // Food LEFT

    // 11..12: Normalized distance delta
    obs[11] = (fx - head.x) / this.gridSize;
    obs[12] = (fy - head.y) / this.gridSize;

    // 13..15: Continuous free space raycasts
    obs[13] = raycast(straight.x, straight.y);
    obs[14] = raycast(right.x, right.y);
    obs[15] = raycast(left.x, left.y);

    return obs;
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 3. HIGH-PERFORMANCE PURE CPU DEEP Q-NETWORK (Float32Array Math)
// ─────────────────────────────────────────────────────────────────────────────
class FastDQN {
  constructor(inputDim = 16, h1Dim = 64, h2Dim = 32, outDim = 3) {
    this.inDim = inputDim;
    this.h1Dim = h1Dim;
    this.h2Dim = h2Dim;
    this.outDim = outDim;

    // Weight matrices & bias vectors
    this.W1 = new Float32Array(h1Dim * inputDim);
    this.b1 = new Float32Array(h1Dim);
    this.W2 = new Float32Array(h2Dim * h1Dim);
    this.b2 = new Float32Array(h2Dim);
    this.W3 = new Float32Array(outDim * h2Dim);
    this.b3 = new Float32Array(outDim);

    this.initHeWeights(this.W1, inputDim);
    this.initHeWeights(this.W2, h1Dim);
    this.initHeWeights(this.W3, h2Dim);

    // Target network parameters
    this.targetW1 = new Float32Array(this.W1);
    this.targetb1 = new Float32Array(this.b1);
    this.targetW2 = new Float32Array(this.W2);
    this.targetb2 = new Float32Array(this.b2);
    this.targetW3 = new Float32Array(this.W3);
    this.targetb3 = new Float32Array(this.b3);

    // Adam optimizer momentum states
    this.mW1 = new Float32Array(this.W1.length);
    this.vW1 = new Float32Array(this.W1.length);
    this.mb1 = new Float32Array(this.b1.length);
    this.vb1 = new Float32Array(this.b1.length);

    this.mW2 = new Float32Array(this.W2.length);
    this.vW2 = new Float32Array(this.W2.length);
    this.mb2 = new Float32Array(this.b2.length);
    this.vb2 = new Float32Array(this.b2.length);

    this.mW3 = new Float32Array(this.W3.length);
    this.vW3 = new Float32Array(this.W3.length);
    this.mb3 = new Float32Array(this.b3.length);
    this.vb3 = new Float32Array(this.b3.length);

    this.t = 0;
    this.lr = 0.001;
    this.gamma = 0.95;

    // Reusable scratch vectors for forward pass
    this.h1 = new Float32Array(h1Dim);
    this.h2 = new Float32Array(h2Dim);
    this.out = new Float32Array(outDim);

    this.targetH1 = new Float32Array(h1Dim);
    this.targetH2 = new Float32Array(h2Dim);
    this.targetOut = new Float32Array(outDim);
  }

  initHeWeights(arr, fanIn) {
    const std = Math.sqrt(2.0 / fanIn);
    for (let i = 0; i < arr.length; i++) {
      const u1 = Math.max(1e-7, Math.random());
      const u2 = Math.random();
      const z = Math.sqrt(-2.0 * Math.log(u1)) * Math.cos(2.0 * Math.PI * u2);
      arr[i] = z * std;
    }
  }

  // Fast forward pass on CPU (< 0.003 ms)
  forward(x, useTarget = false) {
    const W1 = useTarget ? this.targetW1 : this.W1;
    const b1 = useTarget ? this.targetb1 : this.b1;
    const W2 = useTarget ? this.targetW2 : this.W2;
    const b2 = useTarget ? this.targetb2 : this.b2;
    const W3 = useTarget ? this.targetW3 : this.W3;
    const b3 = useTarget ? this.targetb3 : this.b3;
    const h1 = useTarget ? this.targetH1 : this.h1;
    const h2 = useTarget ? this.targetH2 : this.h2;
    const out = useTarget ? this.targetOut : this.out;

    // Layer 1: 16 -> 64 with ReLU
    for (let j = 0; j < this.h1Dim; j++) {
      let sum = b1[j];
      const offset = j * this.inDim;
      for (let i = 0; i < this.inDim; i++) {
        sum += W1[offset + i] * x[i];
      }
      h1[j] = sum > 0 ? sum : 0;
    }

    // Layer 2: 64 -> 32 with ReLU
    for (let j = 0; j < this.h2Dim; j++) {
      let sum = b2[j];
      const offset = j * this.h1Dim;
      for (let i = 0; i < this.h1Dim; i++) {
        sum += W2[offset + i] * h1[i];
      }
      h2[j] = sum > 0 ? sum : 0;
    }

    // Layer 3: 32 -> 3 Linear Q-values
    for (let j = 0; j < this.outDim; j++) {
      let sum = b3[j];
      const offset = j * this.h2Dim;
      for (let i = 0; i < this.h2Dim; i++) {
        sum += W3[offset + i] * h2[i];
      }
      out[j] = sum;
    }

    return out;
  }

  // Soft or hard synchronization with target network
  syncTarget(tau = 1.0) {
    if (tau === 1.0) {
      this.targetW1.set(this.W1);
      this.targetb1.set(this.b1);
      this.targetW2.set(this.W2);
      this.targetb2.set(this.b2);
      this.targetW3.set(this.W3);
      this.targetb3.set(this.b3);
    } else {
      const invTau = 1.0 - tau;
      for (let i = 0; i < this.W1.length; i++) this.targetW1[i] = tau * this.W1[i] + invTau * this.targetW1[i];
      for (let i = 0; i < this.b1.length; i++) this.targetb1[i] = tau * this.b1[i] + invTau * this.targetb1[i];
      for (let i = 0; i < this.W2.length; i++) this.targetW2[i] = tau * this.W2[i] + invTau * this.targetW2[i];
      for (let i = 0; i < this.b2.length; i++) this.targetb2[i] = tau * this.b2[i] + invTau * this.targetb2[i];
      for (let i = 0; i < this.W3.length; i++) this.targetW3[i] = tau * this.W3[i] + invTau * this.targetW3[i];
      for (let i = 0; i < this.b3.length; i++) this.targetb3[i] = tau * this.b3[i] + invTau * this.targetb3[i];
    }
  }

  // Mini-batch backpropagation with Huber Loss and Adam optimizer (< 0.04 ms)
  trainBatch(batch) {
    this.t++;
    const beta1 = 0.9, beta2 = 0.999, eps = 1e-8;
    const lr_t = this.lr * Math.sqrt(1 - Math.pow(beta2, this.t)) / (1 - Math.pow(beta1, this.t));

    const gW1 = new Float32Array(this.W1.length);
    const gb1 = new Float32Array(this.b1.length);
    const gW2 = new Float32Array(this.W2.length);
    const gb2 = new Float32Array(this.b2.length);
    const gW3 = new Float32Array(this.W3.length);
    const gb3 = new Float32Array(this.b3.length);

    let totalLoss = 0;
    const B = batch.length;

    const sampleH1 = new Float32Array(this.h1Dim);
    const sampleH2 = new Float32Array(this.h2Dim);
    const sampleOut = new Float32Array(this.outDim);

    const gradOut = new Float32Array(this.outDim);
    const gradH2 = new Float32Array(this.h2Dim);
    const gradH1 = new Float32Array(this.h1Dim);

    for (let k = 0; k < B; k++) {
      const { s, a, r, nextS, done } = batch[k];

      let targetVal = r;
      if (!done) {
        const nextQ = this.forward(nextS, true);
        let maxNext = nextQ[0];
        if (nextQ[1] > maxNext) maxNext = nextQ[1];
        if (nextQ[2] > maxNext) maxNext = nextQ[2];
        targetVal = r + this.gamma * maxNext;
      }

      // Forward pass for current state s
      for (let j = 0; j < this.h1Dim; j++) {
        let sum = this.b1[j];
        const offset = j * this.inDim;
        for (let i = 0; i < this.inDim; i++) sum += this.W1[offset + i] * s[i];
        sampleH1[j] = sum > 0 ? sum : 0;
      }
      for (let j = 0; j < this.h2Dim; j++) {
        let sum = this.b2[j];
        const offset = j * this.h1Dim;
        for (let i = 0; i < this.h1Dim; i++) sum += this.W2[offset + i] * sampleH1[i];
        sampleH2[j] = sum > 0 ? sum : 0;
      }
      for (let j = 0; j < this.outDim; j++) {
        let sum = this.b3[j];
        const offset = j * this.h2Dim;
        for (let i = 0; i < this.h2Dim; i++) sum += this.W3[offset + i] * sampleH2[i];
        sampleOut[j] = sum;
      }

      const diff = sampleOut[a] - targetVal;
      // Huber loss (Smooth L1) with gradient clipping
      const delta = Math.max(-1.0, Math.min(1.0, diff));
      totalLoss += Math.abs(diff) <= 1 ? 0.5 * diff * diff : Math.abs(diff) - 0.5;

      gradOut.fill(0);
      gradOut[a] = delta / B;

      // Backprop Layer 3
      for (let j = 0; j < this.outDim; j++) {
        const dO = gradOut[j];
        if (dO === 0) continue;
        gb3[j] += dO;
        const offset = j * this.h2Dim;
        for (let i = 0; i < this.h2Dim; i++) {
          gW3[offset + i] += dO * sampleH2[i];
        }
      }

      // Backprop into Hidden Layer 2
      for (let i = 0; i < this.h2Dim; i++) {
        let dH2 = 0;
        for (let j = 0; j < this.outDim; j++) {
          dH2 += gradOut[j] * this.W3[j * this.h2Dim + i];
        }
        gradH2[i] = sampleH2[i] > 0 ? dH2 : 0;
      }

      // Backprop Layer 2
      for (let j = 0; j < this.h2Dim; j++) {
        const dH = gradH2[j];
        if (dH === 0) continue;
        gb2[j] += dH;
        const offset = j * this.h1Dim;
        for (let i = 0; i < this.h1Dim; i++) {
          gW2[offset + i] += dH * sampleH1[i];
        }
      }

      // Backprop into Hidden Layer 1
      for (let i = 0; i < this.h1Dim; i++) {
        let dH1 = 0;
        for (let j = 0; j < this.h2Dim; j++) {
          dH1 += gradH2[j] * this.W2[j * this.h1Dim + i];
        }
        gradH1[i] = sampleH1[i] > 0 ? dH1 : 0;
      }

      // Backprop Layer 1
      for (let j = 0; j < this.h1Dim; j++) {
        const dH = gradH1[j];
        if (dH === 0) continue;
        gb1[j] += dH;
        const offset = j * this.inDim;
        for (let i = 0; i < this.inDim; i++) {
          gW1[offset + i] += dH * s[i];
        }
      }
    }

    // Apply Adam Update
    const applyAdam = (W, gW, mW, vW) => {
      for (let i = 0; i < W.length; i++) {
        const g = gW[i];
        mW[i] = beta1 * mW[i] + (1 - beta1) * g;
        vW[i] = beta2 * vW[i] + (1 - beta2) * g * g;
        W[i] -= (lr_t * mW[i]) / (Math.sqrt(vW[i]) + eps);
      }
    };

    applyAdam(this.W1, gW1, this.mW1, this.vW1);
    applyAdam(this.b1, gb1, this.mb1, this.vb1);
    applyAdam(this.W2, gW2, this.mW2, this.vW2);
    applyAdam(this.b2, gb2, this.mb2, this.vb2);
    applyAdam(this.W3, gW3, this.mW3, this.vW3);
    applyAdam(this.b3, gb3, this.mb3, this.vb3);

    return totalLoss / B;
  }

  loadWeights(data) {
    this.W1.set(data.W1);
    this.b1.set(data.b1);
    this.W2.set(data.W2);
    this.b2.set(data.b2);
    this.W3.set(data.W3);
    this.b3.set(data.b3);
    this.syncTarget(1.0);
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 4. WEB AUDIO SYNTHESIZER (Pure Procedural Synth FX)
// ─────────────────────────────────────────────────────────────────────────────
class SoundSynth {
  constructor() {
    this.ctx = null;
    this.enabled = false;
  }

  init() {
    if (!this.ctx && typeof AudioContext !== 'undefined') {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      this.ctx = new AudioCtx();
    }
  }

  playEat() {
    if (!this.enabled || !this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(587.33, now); // D5
      osc.frequency.exponentialRampToValueAtTime(880.00, now + 0.12); // A5
      gain.gain.setValueAtTime(0.15, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.14);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(now);
      osc.stop(now + 0.14);
    } catch (e) {}
  }

  playCrash() {
    if (!this.enabled || !this.ctx) return;
    try {
      const now = this.ctx.currentTime;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = 'sawtooth';
      osc.frequency.setValueAtTime(140, now);
      osc.frequency.exponentialRampToValueAtTime(40, now + 0.18);
      gain.gain.setValueAtTime(0.18, now);
      gain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);
      osc.connect(gain);
      gain.connect(this.ctx.destination);
      osc.start(now);
      osc.stop(now + 0.18);
    } catch (e) {}
  }
}

// ─────────────────────────────────────────────────────────────────────────────
// 5. MAIN APPLICATION CONTROLLER
// ─────────────────────────────────────────────────────────────────────────────
class SnakeRLApp {
  constructor() {
    this.rng = new SeededRNG(42);
    this.game = new SnakeGame(8, this.rng);
    this.dqn = new FastDQN(16, 64, 32, 3);
    this.synth = new SoundSynth();

    // Reinforcement Learning Hyperparameters
    this.epsilon = 1.0;
    this.epsilonMin = 0.01;
    this.epsilonDecay = 0.994;
    this.isPureGreedy = false; // When true, epsilon is forced to 0
    this.isTurbo = false;
    this.isPaused = false;
    this.speed = 30; // steps per second
    this.lastLoss = 0.0;
    this.totalSteps = 0;
    this.currentEpisode = 1;
    this.bestScore = 0;

    // Experience Replay Memory
    this.replayMemory = [];
    this.maxReplaySize = 20000;
    this.batchSize = 64;

    // Last 30 Runs Performance History
    this.completedRuns = []; // Array of { episode, score, steps, length, epsilon, reason, timestamp }
    this.hoveredRunIndex = -1;

    // Visualization Options
    this.showPerceptionOverlay = true;
    this.particles = [];
    this.theme = 'cyber';

    // Animation & Loop Timings
    this.lastFrameTime = performance.now();
    this.stepAccumulator = 0;
    this.spsCounter = 0;
    this.lastSpsTime = performance.now();
    this.currentSps = 0;

    // Analytics Telemetry Buffers
    this.historyLoss = [];
    this.historyScores = [];
    this.historyEpsilon = [];
    this.historyAvgQ = [];

    this.initDOM();
    this.initCanvases();
    this.bindEvents();
    this.postNarrator('milestone', 'NEURAL ENGINE INITIALIZED', '100% Genuine CPU Deep Q-Network ready. Pure Float32Array SIMD. Zero GPU overhead.');

    requestAnimationFrame(this.mainLoop.bind(this));
  }

  initDOM() {
    // Populate Egocentric Sensor Chips
    const sensorContainer = document.getElementById('state-features-container');
    if (sensorContainer) {
      sensorContainer.innerHTML = '';
      for (let i = 0; i < 16; i++) {
        const chip = document.createElement('div');
        chip.className = 'sensor-chip';
        chip.id = `sensor-chip-${i}`;
        chip.innerHTML = `
          <span class="sensor-lbl">${SENSOR_NAMES[i]}</span>
          <span class="sensor-val" id="sensor-val-${i}">0.00</span>
        `;
        sensorContainer.appendChild(chip);
      }
    }
  }

  initCanvases() {
    this.canvasGame = document.getElementById('canvas-game');
    this.ctxGame = this.canvasGame ? this.canvasGame.getContext('2d') : null;

    this.canvasOverlay = document.getElementById('canvas-overlay');
    this.ctxOverlay = this.canvasOverlay ? this.canvasOverlay.getContext('2d') : null;

    this.canvasLast30 = document.getElementById('canvas-last-30');
    this.ctxLast30 = this.canvasLast30 ? this.canvasLast30.getContext('2d') : null;

    this.canvasBrain = document.getElementById('canvas-live-brain');
    this.ctxBrain = this.canvasBrain ? this.canvasBrain.getContext('2d') : null;

    // Tooltip for Last 30 Runs Chart
    this.tooltipLast30 = document.getElementById('tooltip-last-30');
    if (this.canvasLast30) {
      this.canvasLast30.addEventListener('mousemove', this.onChartMouseMove.bind(this));
      this.canvasLast30.addEventListener('mouseleave', () => {
        this.hoveredRunIndex = -1;
        if (this.tooltipLast30) this.tooltipLast30.style.display = 'none';
        this.renderLast30Chart();
      });
    }
  }

  bindEvents() {
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Space') {
        e.preventDefault();
        this.togglePlayPause();
      }
    });
  }

  // ─────────────────────────────────────────────────────────────────────────
  // THE HEARTBEAT: MAIN APPLICATION LOOP
  // ─────────────────────────────────────────────────────────────────────────
  mainLoop(currentTime) {
    const dt = Math.min(100, currentTime - this.lastFrameTime);
    this.lastFrameTime = currentTime;

    // SPS (Steps Per Second) Benchmark Tracking
    if (currentTime - this.lastSpsTime >= 1000) {
      this.currentSps = this.spsCounter;
      this.spsCounter = 0;
      this.lastSpsTime = currentTime;
      const elHdrSps = document.getElementById('hdr-sps');
      if (elHdrSps) elHdrSps.innerText = this.currentSps;
    }

    if (!this.isPaused) {
      if (this.isTurbo) {
        // High-performance CPU burst: run 40 transitions per animation tick
        const turboSteps = 40;
        for (let i = 0; i < turboSteps; i++) {
          this.executeEnvironmentStep();
        }
      } else {
        // Normal visual speed regulated by speed slider
        const stepInterval = 1000 / this.speed;
        this.stepAccumulator += dt;
        while (this.stepAccumulator >= stepInterval) {
          this.executeEnvironmentStep();
          this.stepAccumulator -= stepInterval;
        }
      }
    }

    // Render Centerpiece Arena & Analytics
    this.renderGame();
    this.renderLiveBrain();

    requestAnimationFrame(this.mainLoop.bind(this));
  }

  // ─────────────────────────────────────────────────────────────────────────
  // THE SINGLE SIMULATION STEP (100% AUDITABLE RL)
  // ─────────────────────────────────────────────────────────────────────────
  executeEnvironmentStep() {
    this.totalSteps++;
    this.spsCounter++;

    const currentState = this.game.getObservation();
    const effectiveEpsilon = this.isPureGreedy ? 0.0 : this.epsilon;

    // Forward Pass on CPU
    const t0 = performance.now();
    const qValues = this.dqn.forward(currentState);
    const latency = performance.now() - t0;

    let selectedAction = 0;
    let isExploratory = false;

    // Action Selection Policy: ε-Greedy
    if (this.rng.next() < effectiveEpsilon) {
      selectedAction = Math.floor(this.rng.next() * 3);
      isExploratory = true;
    } else {
      let maxQ = qValues[0];
      for (let a = 1; a < 3; a++) {
        if (qValues[a] > maxQ) {
          maxQ = qValues[a];
          selectedAction = a;
        }
      }
    }

    // Execute Environment Step
    const stepResult = this.game.step(selectedAction);

    // Sound FX & Sparkle Particles
    if (stepResult.foodEaten) {
      this.synth.playEat();
      this.spawnParticles(this.game.body[0].x, this.game.body[0].y, 'teal');
      if (this.game.score > this.bestScore) {
        this.bestScore = this.game.score;
        this.postNarrator('record', 'NEW RECORD SET!', `Score surpassed ${this.bestScore} apples! Length: ${this.game.body.length}.`);
      }
    }

    if (stepResult.done) {
      if (this.game.deathReason !== 'Victory! Grid Filled') {
        this.synth.playCrash();
        this.spawnParticles(this.game.body[0].x, this.game.body[0].y, 'rose');
      }
    }

    // Store transition into Experience Replay Buffer
    this.replayMemory.push({
      s: currentState,
      a: selectedAction,
      r: stepResult.reward,
      nextS: stepResult.state,
      done: stepResult.done
    });
    if (this.replayMemory.length > this.maxReplaySize) {
      this.replayMemory.shift();
    }

    // Mini-Batch Backpropagation Step
    if (this.replayMemory.length >= this.batchSize && this.totalSteps % 4 === 0) {
      const batch = [];
      for (let i = 0; i < this.batchSize; i++) {
        const randIdx = Math.floor(this.rng.next() * this.replayMemory.length);
        batch.push(this.replayMemory[randIdx]);
      }
      this.lastLoss = this.dqn.trainBatch(batch);
      if (this.totalSteps % 200 === 0) {
        this.historyLoss.push(this.lastLoss);
        if (this.historyLoss.length > 100) this.historyLoss.shift();
      }
    }

    // Periodic Target Network Sync
    if (this.totalSteps % 250 === 0) {
      this.dqn.syncTarget(0.15);
    }

    // Update Live Telemetry & Decisions in UI
    if (!this.isTurbo || this.totalSteps % 10 === 0) {
      this.updateUI(selectedAction, isExploratory, qValues, latency);
    }

    // Episode End Handling
    if (stepResult.done) {
      this.onEpisodeComplete();
    }
  }

  onEpisodeComplete() {
    const epScore = this.game.score;
    const epSteps = this.game.stepsSurvived;
    const epLength = this.game.body.length;
    const epEps = this.epsilon;
    const epReason = this.game.deathReason;

    // Record Run
    this.completedRuns.push({
      episode: this.currentEpisode,
      score: epScore,
      steps: epSteps,
      length: epLength,
      epsilon: epEps,
      reason: epReason,
      timestamp: Date.now()
    });

    this.historyScores.push(epScore);
    if (this.historyScores.length > 200) this.historyScores.shift();

    // Narrative Commentary
    if (this.currentEpisode === 1) {
      this.postNarrator('milestone', 'FIRST EPISODE COMPLETE', `Snake finished Episode 1 (${epReason}). Replay memory seeded.`);
    } else if (epScore >= 15 && epScore > this.bestScore - 2) {
      this.postNarrator('food', 'EXCELLENT RUN!', `Score: ${epScore} apples in ${epSteps} steps. Epsilon: ${epEps.toFixed(3)}.`);
    }

    // Decay Exploration Rate ε
    this.epsilon = Math.max(this.epsilonMin, this.epsilon * this.epsilonDecay);
    this.currentEpisode++;

    // Refresh The Last 30 Runs Performance Panel
    this.updateLast30Panel();

    // Reset Game for next episode
    this.game.reset();
  }

  // ─────────────────────────────────────────────────────────────────────────
  // ⭐ THE LAST 30 RUNS PERFORMANCE TRACKER & INTERACTIVE CANVAS CHART
  // ─────────────────────────────────────────────────────────────────────────
  updateLast30Panel() {
    const last30 = this.completedRuns.slice(-30);
    const n = last30.length;
    if (n === 0) return;

    // 1. Metric Computations
    const totalScore = last30.reduce((acc, r) => acc + r.score, 0);
    const avgScore = totalScore / n;
    const peakScore = Math.max(...last30.map(r => r.score));
    const totalSteps = last30.reduce((acc, r) => acc + r.steps, 0);
    const avgSteps = Math.round(totalSteps / n);
    const efficiency = totalSteps > 0 ? ((totalScore / totalSteps) * 100).toFixed(1) : '0.0';

    // 2. Trend Calculation (compare first half vs second half of the window)
    let trendText = 'SURGING';
    let trendClass = 'badge-teal';
    if (n >= 10) {
      const half = Math.floor(n / 2);
      const earlyHalf = last30.slice(0, half);
      const lateHalf = last30.slice(half);
      const earlyAvg = earlyHalf.reduce((a, b) => a + b.score, 0) / earlyHalf.length;
      const lateAvg = lateHalf.reduce((a, b) => a + b.score, 0) / lateHalf.length;
      const diff = lateAvg - earlyAvg;
      if (diff > 1.5) {
        trendText = `▲ +${Math.round((diff / Math.max(1, earlyAvg)) * 100)}% Surge`;
        trendClass = 'badge-teal';
      } else if (diff < -1.5) {
        trendText = '▼ Re-exploring';
        trendClass = 'badge-amber';
      } else {
        trendText = '★ Stable Policy';
        trendClass = 'badge-cyan';
      }
    }

    // Update DOM Metrics
    const elAvg = document.getElementById('l30-avg');
    if (elAvg) elAvg.innerText = avgScore.toFixed(2);
    const elPeak = document.getElementById('l30-peak');
    if (elPeak) elPeak.innerText = peakScore;
    const elSteps = document.getElementById('l30-steps');
    if (elSteps) elSteps.innerText = avgSteps;
    const elEff = document.getElementById('l30-efficiency');
    if (elEff) elEff.innerText = `${efficiency}%`;
    const elBadgeTrend = document.getElementById('badge-runs-trend');
    if (elBadgeTrend) {
      elBadgeTrend.innerText = trendText;
      elBadgeTrend.className = `badge ${trendClass}`;
    }

    // 3. Render Canvas Chart
    this.renderLast30Chart();

    // 4. Update History Feed
    this.renderLast30HistoryList();
  }

  renderLast30Chart() {
    if (!this.ctxLast30 || !this.canvasLast30) return;
    const ctx = this.ctxLast30;
    const width = this.canvasLast30.width;
    const height = this.canvasLast30.height;

    ctx.clearRect(0, 0, width, height);

    const runs = this.completedRuns.slice(-30);
    const totalSlots = 30;
    const padX = 14;
    const padY = 16;
    const chartW = width - padX * 2;
    const chartH = height - padY * 2;

    // Draw Subtle Background Grid
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.04)';
    ctx.lineWidth = 1;
    for (let y = padY; y <= height - padY; y += chartH / 4) {
      ctx.beginPath();
      ctx.moveTo(padX, y);
      ctx.lineTo(width - padX, y);
      ctx.stroke();
    }

    if (runs.length === 0) {
      ctx.fillStyle = '#4e5d78';
      ctx.font = '11px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Awaiting first episode completion…', width / 2, height / 2);
      return;
    }

    // Determine Scaling Range
    const maxScore = Math.max(10, ...runs.map(r => r.score), this.bestScore);
    const slotW = chartW / totalSlots;
    const barW = Math.max(4, slotW - 3);

    // Compute 10-Run Moving Average Coordinates
    const trendPoints = [];
    let movingSum = 0;
    for (let i = 0; i < runs.length; i++) {
      const windowStart = Math.max(0, i - 9);
      const sub = runs.slice(windowStart, i + 1);
      const avg = sub.reduce((a, b) => a + b.score, 0) / sub.length;
      const x = padX + i * slotW + slotW / 2;
      const y = height - padY - (avg / maxScore) * chartH;
      trendPoints.push({ x, y, avg });
    }

    // 1. Render Bars for Last 30 Runs
    for (let i = 0; i < runs.length; i++) {
      const r = runs[i];
      const isHovered = (i === this.hoveredRunIndex);
      const barH = Math.max(4, (r.score / maxScore) * chartH);
      const x = padX + i * slotW + (slotW - barW) / 2;
      const y = height - padY - barH;

      // Color coding based on performance
      let grad = ctx.createLinearGradient(0, y, 0, height - padY);
      if (r.score >= 12) {
        grad.addColorStop(0, '#ffd700'); // Gold for masters
        grad.addColorStop(1, 'rgba(0, 229, 163, 0.4)');
      } else if (r.score >= 5) {
        grad.addColorStop(0, '#00e5ff'); // Cyan for solid runs
        grad.addColorStop(1, 'rgba(0, 229, 255, 0.3)');
      } else {
        grad.addColorStop(0, '#b388ff'); // Violet for exploration
        grad.addColorStop(1, 'rgba(179, 136, 255, 0.2)');
      }

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.roundRect(x, y, barW, barH, [3, 3, 0, 0]);
      ctx.fill();

      // Highlight active hovered bar
      if (isHovered) {
        ctx.strokeStyle = '#00e5ff';
        ctx.lineWidth = 2;
        ctx.stroke();
      }
    }

    // 2. Render Moving Average Trendline Overlay
    if (trendPoints.length > 1) {
      ctx.beginPath();
      ctx.moveTo(trendPoints[0].x, trendPoints[0].y);
      for (let i = 1; i < trendPoints.length; i++) {
        ctx.lineTo(trendPoints[i].x, trendPoints[i].y);
      }
      ctx.strokeStyle = '#ffd700';
      ctx.lineWidth = 2.5;
      ctx.shadowColor = 'rgba(255, 215, 0, 0.5)';
      ctx.shadowBlur = 8;
      ctx.stroke();
      ctx.shadowBlur = 0; // reset
    }

    // 3. Render High-Water Mark Benchmark (Dashed line)
    if (this.bestScore > 0) {
      const bestY = height - padY - (this.bestScore / maxScore) * chartH;
      ctx.strokeStyle = 'rgba(255, 215, 0, 0.35)';
      ctx.setLineDash([4, 4]);
      ctx.beginPath();
      ctx.moveTo(padX, bestY);
      ctx.lineTo(width - padX, bestY);
      ctx.stroke();
      ctx.setLineDash([]); // reset
    }
  }

  onChartMouseMove(e) {
    if (!this.canvasLast30) return;
    const rect = this.canvasLast30.getBoundingClientRect();
    const mouseX = e.clientX - rect.left;
    const runs = this.completedRuns.slice(-30);
    if (runs.length === 0) return;

    const padX = 14;
    const chartW = this.canvasLast30.width - padX * 2;
    const slotW = chartW / 30;

    const index = Math.floor((mouseX - padX) / slotW);
    if (index >= 0 && index < runs.length) {
      this.hoveredRunIndex = index;
      const run = runs[index];

      if (this.tooltipLast30) {
        this.tooltipLast30.style.display = 'block';
        this.tooltipLast30.style.left = `${e.clientX - rect.left}px`;
        this.tooltipLast30.style.top = `${e.clientY - rect.top}px`;
        this.tooltipLast30.innerHTML = `
          <strong>Episode #${run.episode}</strong><br>
          <span style="color:var(--teal)">Score: ${run.score} 🍎</span> | Steps: ${run.steps}<br>
          <span style="color:var(--text-dim)">Length: ${run.length} | ε: ${run.epsilon.toFixed(3)}</span><br>
          <span style="color:var(--amber)">Cause: ${run.reason}</span>
        `;
      }
    } else {
      this.hoveredRunIndex = -1;
      if (this.tooltipLast30) this.tooltipLast30.style.display = 'none';
    }
    this.renderLast30Chart();
  }

  renderLast30HistoryList() {
    const listEl = document.getElementById('runs-history-list');
    const countEl = document.getElementById('txt-history-count');
    if (!listEl) return;

    const runs = this.completedRuns.slice(-30).reverse();
    if (countEl) countEl.innerText = `${runs.length} / 30 recorded`;

    if (runs.length === 0) {
      listEl.innerHTML = '<div class="empty-history-hint">Awaiting first episode completion…</div>';
      return;
    }

    listEl.innerHTML = runs.map(r => {
      let tagClass = 'wall';
      if (r.reason.includes('Self')) tagClass = 'self';
      else if (r.reason.includes('Starve')) tagClass = 'starve';

      const isHigh = r.score >= 10;
      return `
        <div class="run-item">
          <div class="run-item-left">
            <span class="run-num">#${r.episode}</span>
            <span class="run-score ${isHigh ? 'high' : ''}">${r.score} 🍎</span>
          </div>
          <div class="run-item-right">
            <span>${r.steps} steps</span>
            <span class="death-tag ${tagClass}">${r.reason.replace(' Collision', '')}</span>
          </div>
        </div>
      `;
    }).join('');
  }

  // ─────────────────────────────────────────────────────────────────────────
  // ARENA CENTERPIECE HIGH-DPI CANVAS RENDERING
  // ─────────────────────────────────────────────────────────────────────────
  renderGame() {
    if (!this.ctxGame || !this.canvasGame) return;
    const ctx = this.ctxGame;
    const size = this.canvasGame.width;
    const grid = this.game.gridSize;
    const cell = size / grid;

    ctx.clearRect(0, 0, size, size);

    // 1. Ambient Grid Lines
    ctx.strokeStyle = 'rgba(255, 255, 255, 0.035)';
    ctx.lineWidth = 1;
    for (let i = 0; i <= grid; i++) {
      ctx.beginPath();
      ctx.moveTo(i * cell, 0);
      ctx.lineTo(i * cell, size);
      ctx.stroke();

      ctx.beginPath();
      ctx.moveTo(0, i * cell);
      ctx.lineTo(size, i * cell);
      ctx.stroke();
    }

    // 2. Pulsing Neon Food (Apple)
    if (this.game.food) {
      const fx = this.game.food.x * cell + cell / 2;
      const fy = this.game.food.y * cell + cell / 2;
      const pulse = 1 + 0.08 * Math.sin(Date.now() * 0.008);
      const rad = (cell / 2.6) * pulse;

      // Glow halo
      const grad = ctx.createRadialGradient(fx, fy, 0, fx, fy, rad * 2);
      grad.addColorStop(0, 'rgba(255, 51, 102, 0.9)');
      grad.addColorStop(0.5, 'rgba(255, 51, 102, 0.3)');
      grad.addColorStop(1, 'rgba(255, 51, 102, 0)');

      ctx.fillStyle = grad;
      ctx.beginPath();
      ctx.arc(fx, fy, rad * 2, 0, Math.PI * 2);
      ctx.fill();

      // Apple core
      ctx.fillStyle = '#ff3366';
      ctx.beginPath();
      ctx.arc(fx, fy, rad, 0, Math.PI * 2);
      ctx.fill();

      // Apple leaf/stem
      ctx.fillStyle = '#00ff9d';
      ctx.beginPath();
      ctx.arc(fx, fy - rad * 0.9, rad * 0.35, 0, Math.PI * 2);
      ctx.fill();
    }

    // 3. Snake Body Rendering
    const body = this.game.body;
    for (let i = body.length - 1; i >= 0; i--) {
      const seg = body[i];
      const px = seg.x * cell;
      const py = seg.y * cell;
      const pad = 2;

      if (i === 0) {
        // Snake Head: Vibrant Cyan with Gradient
        ctx.fillStyle = '#00e5ff';
        ctx.shadowColor = 'rgba(0, 229, 255, 0.6)';
        ctx.shadowBlur = 12;
        ctx.beginPath();
        ctx.roundRect(px + pad, py + pad, cell - pad * 2, cell - pad * 2, 8);
        ctx.fill();
        ctx.shadowBlur = 0; // reset

        // Directional Animated Eyes with Pupils
        this.renderSnakeEyes(ctx, px, py, cell, this.game.dir);
      } else {
        // Snake Body: Gradient Shading from Cyan to Teal
        const t = i / Math.max(1, body.length);
        const rVal = Math.round(0 + t * 0);
        const gVal = Math.round(229 - t * 30);
        const bVal = Math.round(255 - t * 90);
        ctx.fillStyle = `rgb(${rVal}, ${gVal}, ${bVal})`;

        ctx.beginPath();
        ctx.roundRect(px + pad, py + pad, cell - pad * 2, cell - pad * 2, 6);
        ctx.fill();
      }
    }

    // 4. Perception Raycast Whiskers (Overlay)
    if (this.showPerceptionOverlay && this.ctxOverlay && this.canvasOverlay) {
      this.renderRaycasts(this.ctxOverlay, size, cell);
    }

    // 5. Particle Bursts
    this.renderParticles(ctx);

    // Collision Flash Effect
    const boardWrap = document.getElementById('board-wrapper');
    if (boardWrap) {
      if (this.game.deathFlash > 0) {
        this.game.deathFlash--;
        boardWrap.classList.add('death-flash');
      } else {
        boardWrap.classList.remove('death-flash');
      }
    }
  }

  renderSnakeEyes(ctx, px, py, cell, dir) {
    const eyeSize = Math.max(3, cell * 0.18);
    const pupilSize = eyeSize * 0.55;
    let eye1X, eye1Y, eye2X, eye2Y;
    let pupDx = 0, pupDy = 0;

    if (dir === 0) { // UP
      eye1X = px + cell * 0.28; eye1Y = py + cell * 0.3;
      eye2X = px + cell * 0.72; eye2Y = py + cell * 0.3;
      pupDy = -pupilSize * 0.4;
    } else if (dir === 1) { // RIGHT
      eye1X = px + cell * 0.7; eye1Y = py + cell * 0.28;
      eye2X = px + cell * 0.7; eye2Y = py + cell * 0.72;
      pupDx = pupilSize * 0.4;
    } else if (dir === 2) { // DOWN
      eye1X = px + cell * 0.28; eye1Y = py + cell * 0.7;
      eye2X = px + cell * 0.72; eye2Y = py + cell * 0.7;
      pupDy = pupilSize * 0.4;
    } else { // LEFT
      eye1X = px + cell * 0.3; eye1Y = py + cell * 0.28;
      eye2X = px + cell * 0.3; eye2Y = py + cell * 0.72;
      pupDx = -pupilSize * 0.4;
    }

    // White eye sclera
    ctx.fillStyle = '#ffffff';
    ctx.beginPath(); ctx.arc(eye1X, eye1Y, eyeSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(eye2X, eye2Y, eyeSize, 0, Math.PI * 2); ctx.fill();

    // Black pupils focused towards heading
    ctx.fillStyle = '#05070d';
    ctx.beginPath(); ctx.arc(eye1X + pupDx, eye1Y + pupDy, pupilSize, 0, Math.PI * 2); ctx.fill();
    ctx.beginPath(); ctx.arc(eye2X + pupDx, eye2Y + pupDy, pupilSize, 0, Math.PI * 2); ctx.fill();
  }

  renderRaycasts(ctx, size, cell) {
    ctx.clearRect(0, 0, size, size);
    if (this.game.isDead) return;

    const head = this.game.body[0];
    const hx = head.x * cell + cell / 2;
    const hy = head.y * cell + cell / 2;

    const castDirs = [
      DIRS[this.game.dir],                 // Straight
      DIRS[(this.game.dir + 1) % 4],       // Right
      DIRS[(this.game.dir + 3) % 4]        // Left
    ];

    ctx.lineWidth = 1.5;
    for (let k = 0; k < castDirs.length; k++) {
      const d = castDirs[k];
      let cx = head.x + d.x;
      let cy = head.y + d.y;
      let blocked = false;

      while (cx >= 0 && cx < this.game.gridSize && cy >= 0 && cy < this.game.gridSize) {
        for (let i = 0; i < this.game.body.length - 1; i++) {
          if (this.game.body[i].x === cx && this.game.body[i].y === cy) {
            blocked = true;
            break;
          }
        }
        if (blocked) break;
        cx += d.x;
        cy += d.y;
      }

      const endX = cx * cell + cell / 2;
      const endY = cy * cell + cell / 2;

      ctx.strokeStyle = k === 0 ? 'rgba(0, 229, 255, 0.4)' : 'rgba(179, 136, 255, 0.3)';
      ctx.beginPath();
      ctx.moveTo(hx, hy);
      ctx.lineTo(endX, endY);
      ctx.stroke();

      // End sensor marker
      ctx.fillStyle = blocked ? '#ff4772' : '#00e5a3';
      ctx.beginPath();
      ctx.arc(endX, endY, 3, 0, Math.PI * 2);
      ctx.fill();
    }
  }

  spawnParticles(gridX, gridY, type = 'teal') {
    const cell = 500 / this.game.gridSize;
    const cx = gridX * cell + cell / 2;
    const cy = gridY * cell + cell / 2;
    for (let i = 0; i < 14; i++) {
      const angle = Math.random() * Math.PI * 2;
      const speed = 1.5 + Math.random() * 3.5;
      this.particles.push({
        x: cx,
        y: cy,
        vx: Math.cos(angle) * speed,
        vy: Math.sin(angle) * speed,
        life: 1.0,
        decay: 0.04 + Math.random() * 0.03,
        color: type === 'rose' ? '#ff3366' : '#00e5a3'
      });
    }
  }

  renderParticles(ctx) {
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.x += p.vx;
      p.y += p.vy;
      p.life -= p.decay;

      if (p.life <= 0) {
        this.particles.splice(i, 1);
        continue;
      }

      ctx.fillStyle = p.color;
      ctx.globalAlpha = p.life;
      ctx.beginPath();
      ctx.arc(p.x, p.y, 2.5 * p.life, 0, Math.PI * 2);
      ctx.fill();
      ctx.globalAlpha = 1.0;
    }
  }

  // ─────────────────────────────────────────────────────────────────────────
  // LIVE NEURAL BRAIN VISUALIZER (Real ReLU Activations)
  // ─────────────────────────────────────────────────────────────────────────
  renderLiveBrain() {
    if (!this.ctxBrain || !this.canvasBrain) return;
    const ctx = this.ctxBrain;
    const width = this.canvasBrain.width;
    const height = this.canvasBrain.height;

    ctx.clearRect(0, 0, width, height);

    const layers = [
      { name: 'In', count: 16, x: 25, values: this.game.getObservation() },
      { name: 'H1', count: 18, x: 135, values: this.dqn.h1.slice(0, 18) },
      { name: 'H2', count: 14, x: 245, values: this.dqn.h2.slice(0, 14) },
      { name: 'Q', count: 3, x: 350, values: this.dqn.out }
    ];

    // Synaptic connections (subtle glowing lines)
    ctx.lineWidth = 0.5;
    for (let l = 0; l < layers.length - 1; l++) {
      const l1 = layers[l];
      const l2 = layers[l + 1];
      const step1 = height / (l1.count + 1);
      const step2 = height / (l2.count + 1);

      for (let i = 0; i < l1.count; i += 2) {
        const y1 = (i + 1) * step1;
        for (let j = 0; j < l2.count; j += 2) {
          const y2 = (j + 1) * step2;
          ctx.strokeStyle = 'rgba(0, 229, 255, 0.05)';
          ctx.beginPath();
          ctx.moveTo(l1.x, y1);
          ctx.lineTo(l2.x, y2);
          ctx.stroke();
        }
      }
    }

    // Neurons with live activation glow
    for (let l = 0; l < layers.length; l++) {
      const layer = layers[l];
      const step = height / (layer.count + 1);

      for (let i = 0; i < layer.count; i++) {
        const y = (i + 1) * step;
        const val = layer.values[i] || 0;
        const norm = Math.min(1.0, Math.max(0.0, Math.abs(val)));

        // Glowing node
        ctx.fillStyle = l === 3 ? '#ffd700' : (val > 0.01 ? '#00e5ff' : '#1c2740');
        ctx.beginPath();
        ctx.arc(layer.x, y, 3.5, 0, Math.PI * 2);
        ctx.fill();

        if (norm > 0.3) {
          ctx.strokeStyle = `rgba(0, 229, 255, ${norm * 0.8})`;
          ctx.stroke();
        }
      }
    }
  }

  // ─────────────────────────────────────────────────────────────────────────
  // UI & TELEMETRY UPDATES
  // ─────────────────────────────────────────────────────────────────────────
  updateUI(action, isExploratory, qValues, latency) {
    // 1. Header pills
    const elHdrScore = document.getElementById('hdr-score');
    if (elHdrScore) elHdrScore.innerText = this.game.score;
    const elHdrBest = document.getElementById('hdr-best');
    if (elHdrBest) elHdrBest.innerText = this.bestScore;
    const elHdrEp = document.getElementById('hdr-episode');
    if (elHdrEp) elHdrEp.innerText = this.currentEpisode;
    const elHdrEps = document.getElementById('hdr-epsilon');
    if (elHdrEps) elHdrEps.innerText = this.isPureGreedy ? '0.000' : this.epsilon.toFixed(3);

    // 2. Stat chips
    const elStatScore = document.getElementById('stat-score');
    if (elStatScore) elStatScore.innerText = this.game.score;
    const elStatLen = document.getElementById('stat-length');
    if (elStatLen) elStatLen.innerText = this.game.body.length;
    const elStatSteps = document.getElementById('stat-steps');
    if (elStatSteps) elStatSteps.innerText = this.game.stepsSurvived;
    const elStatEp = document.getElementById('stat-episode');
    if (elStatEp) elStatEp.innerText = this.currentEpisode;
    const elStatBest = document.getElementById('stat-best');
    if (elStatBest) elStatBest.innerText = this.bestScore;

    const totalCells = this.game.gridSize * this.game.gridSize;
    const fillPct = ((this.game.body.length / totalCells) * 100).toFixed(1);
    const elStatFill = document.getElementById('stat-fill');
    if (elStatFill) elStatFill.innerText = `${fillPct}%`;
    const elFillFill = document.getElementById('fill-bar-fill');
    if (elFillFill) elFillFill.style.width = `${fillPct}%`;
    const elFillCount = document.getElementById('fill-cell-count');
    if (elFillCount) elFillCount.innerText = `${this.game.body.length} / ${totalCells} cells`;

    // 3. Decision Card
    const elActionSource = document.getElementById('txt-action-source');
    if (elActionSource) elActionSource.innerText = ACTION_NAMES[action];
    const elBadgeDecision = document.getElementById('badge-decision-type');
    if (elBadgeDecision) {
      elBadgeDecision.innerText = isExploratory ? 'EXPLORE' : 'EXPLOIT';
      elBadgeDecision.className = isExploratory ? 'badge badge-violet' : 'badge badge-cyan';
    }
    const elBadgePolicy = document.getElementById('badge-policy-mode');
    if (elBadgePolicy) {
      elBadgePolicy.innerText = isExploratory ? 'Random ε-Move' : 'Q-Policy (argmax)';
      elBadgePolicy.style.color = isExploratory ? 'var(--violet)' : 'var(--cyan)';
    }

    // 4. Q-Values bars
    const maxQ = Math.max(0.01, Math.abs(qValues[0]), Math.abs(qValues[1]), Math.abs(qValues[2]));
    for (let a = 0; a < 3; a++) {
      const elVal = document.getElementById(`q-val-${a}`);
      if (elVal) elVal.innerText = qValues[a].toFixed(2);
      const elBar = document.getElementById(`q-bar-${a}`);
      if (elBar) {
        const pct = Math.max(5, Math.min(100, Math.round(((qValues[a] + maxQ) / (2 * maxQ)) * 100)));
        elBar.style.width = `${pct}%`;
      }
    }

    // 5. Perception Sensors (16 items)
    const obs = this.game.getObservation();
    for (let i = 0; i < 16; i++) {
      const elVal = document.getElementById(`sensor-val-${i}`);
      const elChip = document.getElementById(`sensor-chip-${i}`);
      if (elVal && elChip) {
        const v = obs[i];
        elVal.innerText = v.toFixed(2);
        if (i < 3) {
          elChip.className = v > 0.5 ? 'sensor-chip danger-on' : 'sensor-chip';
        } else {
          elChip.className = Math.abs(v) > 0.05 ? 'sensor-chip active-on' : 'sensor-chip';
        }
      }
    }

    // 6. Telemetry panel
    const elLoss = document.getElementById('data-loss');
    if (elLoss) elLoss.innerText = this.lastLoss.toFixed(4);
    const elAvgQ = document.getElementById('data-avg-q');
    if (elAvgQ) {
      const avgQ = (qValues[0] + qValues[1] + qValues[2]) / 3;
      elAvgQ.innerText = avgQ.toFixed(3);
    }
    const elLatency = document.getElementById('data-latency');
    if (elLatency) elLatency.innerText = `${(latency || 0.002).toFixed(3)} ms`;
    const elTotalSteps = document.getElementById('data-total-steps');
    if (elTotalSteps) elTotalSteps.innerText = this.totalSteps.toLocaleString();
    const elBufSize = document.getElementById('data-buffer-size');
    if (elBufSize) elBufSize.innerText = `${this.replayMemory.length.toLocaleString()} / 20k`;

    // Starvation timer
    const maxStarve = Math.max(100, this.game.body.length * 60);
    const elStarve = document.getElementById('data-starvation');
    if (elStarve) elStarve.innerText = `${this.game.stepsWithoutFood} / ${maxStarve}`;
    const elStarveFill = document.getElementById('data-starvation-fill');
    if (elStarveFill) {
      const starvePct = Math.min(100, Math.round((this.game.stepsWithoutFood / maxStarve) * 100));
      elStarveFill.style.width = `${starvePct}%`;
    }
  }

  postNarrator(type, title, message) {
    const container = document.getElementById('narrator-stream');
    if (!container) return;

    const time = new Date().toLocaleTimeString('en-US', { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
    const entry = document.createElement('div');
    entry.className = `narrator-entry ${type}`;
    entry.innerHTML = `
      <div><span class="narrator-time">[${time}]</span><strong>${title}</strong></div>
      <div>${message}</div>
    `;

    container.insertBefore(entry, container.firstChild);
    while (container.children.length > 25) {
      container.removeChild(container.lastChild);
    }
  }

  // ─────────────────────────────────────────────────────────────────────────
  // USER CONTROLS & INTERACTIVE ACTIONS
  // ─────────────────────────────────────────────────────────────────────────
  togglePlayPause() {
    this.isPaused = !this.isPaused;
    const btn = document.getElementById('btn-play-pause');
    const dot = document.getElementById('dot-live');
    const txt = document.getElementById('txt-engine-status');

    if (this.isPaused) {
      if (btn) btn.innerText = '▶ Resume';
      if (dot) dot.className = 'telemetry-dot paused';
      if (txt) txt.innerText = 'Paused';
    } else {
      if (btn) btn.innerText = '⏸ Pause';
      if (dot) dot.className = 'telemetry-dot active';
      if (txt) txt.innerText = 'Running Live';
    }
  }

  stepSingleMove() {
    if (!this.isPaused) this.togglePlayPause();
    this.executeEnvironmentStep();
  }

  toggleBestMode() {
    this.isPureGreedy = !this.isPureGreedy;
    const btn = document.getElementById('btn-best-mode');
    if (btn) {
      if (this.isPureGreedy) {
        btn.innerText = '🎯 Pure Greedy (ε=0): ACTIVE';
        btn.classList.add('active');
        this.postNarrator('milestone', 'GREEDY MODE ENGAGED', 'Exploration forced to 0. Snake is executing pure learned policy without random mistakes.');
      } else {
        btn.innerText = '🎯 Pure Greedy (ε=0): OFF';
        btn.classList.remove('active');
        this.postNarrator('milestone', 'EXPLORATION RESTORED', `Exploration epsilon restored to ${this.epsilon.toFixed(3)}.`);
      }
    }
  }

  toggleTurbo() {
    this.isTurbo = !this.isTurbo;
    const btn = document.getElementById('btn-turbo');
    if (btn) {
      if (this.isTurbo) {
        btn.innerText = '⚡ Turbo: 1000+ SPS';
        btn.classList.add('active');
        this.postNarrator('milestone', 'MAX CPU TURBO ENGAGED', 'Simulating at maximum CPU throughput. Bypassing animation throttle.');
      } else {
        btn.innerText = '⚡ Turbo Train: OFF';
        btn.classList.remove('active');
        this.postNarrator('milestone', 'VISUAL MODE RESTORED', `Simulation throttled to ${this.speed} steps per second.`);
      }
    }
  }

  loadChampionWeights() {
    this.dqn.loadWeights(CHAMPION_WEIGHTS);
    this.epsilon = 0.01;
    this.isPureGreedy = true;
    const btnBest = document.getElementById('btn-best-mode');
    if (btnBest) {
      btnBest.innerText = '🎯 Pure Greedy (ε=0): ACTIVE';
      btnBest.classList.add('active');
    }
    this.postNarrator('record', '🏆 MASTER BRAIN LOADED', 'Pre-trained champion weights activated! Epsilon set to 0. Watch high-level play with 20-30+ apples.');
  }

  restartFromScratch() {
    this.rng.reset(Date.now() & 0xffffffff);
    this.dqn = new FastDQN(16, 64, 32, 3);
    this.epsilon = 1.0;
    this.isPureGreedy = false;
    this.replayMemory = [];
    this.currentEpisode = 1;
    this.totalSteps = 0;
    this.bestScore = 0;
    this.completedRuns = [];

    const btnBest = document.getElementById('btn-best-mode');
    if (btnBest) {
      btnBest.innerText = '🎯 Pure Greedy (ε=0): OFF';
      btnBest.classList.remove('active');
    }

    this.game.reset();
    this.updateLast30Panel();
    this.postNarrator('milestone', 'NETWORK REINITIALIZED', 'He-Normal weights randomized. Epsilon reset to 1.0. Watching intelligence emerge from scratch!');
  }

  setSpeed(val) {
    this.speed = parseInt(val, 10);
    const label = document.getElementById('speed-label');
    if (label) label.innerText = `${this.speed} st/s`;
  }

  changeGridSize(sizeStr) {
    const size = parseInt(sizeStr, 10);
    this.game = new SnakeGame(size, this.rng);
    this.postNarrator('milestone', 'BOARD RESIZED', `Grid dimension changed to ${size} × ${size} (${size * size} cells).`);
  }

  changeTheme(themeName) {
    this.theme = themeName;
    document.body.className = `theme-${themeName}`;
  }

  togglePerceptionOverlay(checked) {
    this.showPerceptionOverlay = checked;
  }

  toggleAudio() {
    this.synth.init();
    this.synth.enabled = !this.synth.enabled;
    const btn = document.getElementById('btn-audio');
    if (btn) {
      btn.innerText = this.synth.enabled ? '🔊 Sound: ON' : '🔇 Sound: OFF';
      btn.classList.toggle('active', this.synth.enabled);
    }
  }

  switchTab(tabKey) {
    const tabs = ['live', 'model', 'stats', 'code', 'learn'];
    const navBtns = document.querySelectorAll('.nav-tab-btn');

    navBtns.forEach((btn, idx) => {
      btn.classList.toggle('active', tabs[idx] === tabKey);
    });

    tabs.forEach(t => {
      const pane = document.getElementById(`pane-${t}`);
      if (pane) pane.classList.toggle('active', t === tabKey);
    });

    if (tabKey === 'stats') {
      this.renderAnalyticsCharts();
    }
  }

  openIntegrityModal() {
    const modal = document.getElementById('modal-audit');
    if (modal) modal.style.display = 'flex';
  }

  closeIntegrityModal() {
    const modal = document.getElementById('modal-audit');
    if (modal) modal.style.display = 'none';
  }

  // ─────────────────────────────────────────────────────────────────────────
  // ANALYTICS LAB TAB PLOTS
  // ─────────────────────────────────────────────────────────────────────────
  renderAnalyticsCharts() {
    this.renderLineChart('chart-loss', this.historyLoss, 'Huber Loss', '#00e5ff');
    this.renderLineChart('chart-all-scores', this.historyScores, 'Episode Score', '#00e5a3');
  }

  renderLineChart(canvasId, data, label, color) {
    const canvas = document.getElementById(canvasId);
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;

    ctx.clearRect(0, 0, w, h);
    if (data.length < 2) {
      ctx.fillStyle = '#4e5d78';
      ctx.font = '11px Inter, sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('Accumulating learning telemetry data…', w / 2, h / 2);
      return;
    }

    const pad = 25;
    const maxVal = Math.max(1, Math.max(...data));
    const stepX = (w - pad * 2) / (data.length - 1);

    ctx.strokeStyle = 'rgba(255, 255, 255, 0.05)';
    ctx.beginPath();
    ctx.moveTo(pad, h - pad);
    ctx.lineTo(w - pad, h - pad);
    ctx.stroke();

    ctx.strokeStyle = color;
    ctx.lineWidth = 2;
    ctx.beginPath();
    for (let i = 0; i < data.length; i++) {
      const x = pad + i * stepX;
      const y = h - pad - (data[i] / maxVal) * (h - pad * 2);
      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

